pub fn lru(capacity: Int, ops: List[Str]) -> List[Str] {
  var keys: List[Str] = []
  var vals: Map[Str, Str] = Map {}
  var results: List[Str] = []
  for op in ops {
    let parts = op.split(" ")
    let cmd = parts.get_or(0, "")
    let k = parts.get_or(1, "")
    if cmd == "put" {
      let v = parts.get_or(2, "")
      if capacity > 0 {
        if (not vals.has(k)) and (keys.len() >= capacity) {
          let oldest = keys.get_or(0, "")
          keys = keys.drop(1)
          vals = vals.remove(oldest)
        }
        vals = vals.set(k, v)
        keys = touch(keys, k)
      }
    } else {
      if vals.has(k) {
        results = results.push(vals.get(k).unwrap_or("-"))
        keys = touch(keys, k)
      } else {
        results = results.push("-")
      }
    }
  }
  return results
}
