pub fn paths(n: Int, edges: List[List[Int]], src: Int) -> List[Int] {
  var dist: List[Int] = []
  for _i in range(0, n) {
    dist = dist.push(-1)
  }
  if src >= 0 and src < n {
    dist = dist.set(src, 0)
  }
  for _round in range(0, n) {
    for e in edges {
      let u = e.get_or(0, 0)
      let v = e.get_or(1, 0)
      let w = e.get_or(2, 0)
      let du = dist.get_or(u, -1)
      let dv = dist.get_or(v, -1)
      if du >= 0 {
        let cand = du + w
        if dv < 0 or cand < dv {
          dist = dist.set(v, cand)
        }
      }
    }
  }
  return dist
}
