fn unit_rank(c: Str) -> Int {
  if c == "d" {
    return 0
  }
  if c == "h" {
    return 1
  }
  if c == "m" {
    return 2
  }
  if c == "s" {
    return 3
  }
  return -1
}

fn unit_secs(rank: Int) -> Int {
  return match rank {
    0 => 86400,
    1 => 3600,
    2 => 60,
    _ => 1,
  }
}

pub fn duration(s: Str) -> Result[Int, Str] {
  var total = 0
  var num = ""
  var last = -1
  for c in s.chars() {
    if "0123456789".contains(c) {
      num = num + c
    } else {
      let rank = unit_rank(c)
      if rank < 0 or num == "" or rank <= last {
        return Err("invalid duration")
      }
      let amount = num.to_int().unwrap_or(0)
      total = total + amount * unit_secs(rank)
      last = rank
      num = ""
    }
  }
  if num != "" or last < 0 {
    return Err("invalid duration")
  }
  return Ok(total)
}
