pub fn edit(a: Str, b: Str) -> Int {
  let ca = a.chars()
  let cb = b.chars()
  let n = ca.len()
  let m = cb.len()
  var prev = range(0, m + 1)
  for i in range(1, n + 1) {
    var row: List[Int] = [i]
    for j in range(1, m + 1) {
      let cost = match ca.get_or(i - 1, "") == cb.get_or(j - 1, "") {
        true => 0,
        false => 1,
      }
      let sub_cost = prev.get_or(j - 1, 0) + cost
      let dele = prev.get_or(j, 0) + 1
      let ins = row.get_or(j - 1, 0) + 1
      row = row.push(dele.min(ins).min(sub_cost))
    }
    prev = row
  }
  return prev.get_or(m, 0)
}
