pub fn spiral(m: List[List[Int]]) -> List[Int] {
  let none_row: List[Int] = []
  let rows = m.len()
  let cols = m.get_or(0, none_row).len()
  var out: List[Int] = []
  var top = 0
  var bottom = rows - 1
  var left = 0
  var right = cols - 1
  while top <= bottom and left <= right {
    for c in range(left, right + 1) {
      out = out.push(m.get_or(top, none_row).get_or(c, 0))
    }
    top = top + 1
    for r in range(top, bottom + 1) {
      out = out.push(m.get_or(r, none_row).get_or(right, 0))
    }
    right = right - 1
    if top <= bottom {
      for c in range(left, right + 1).reverse() {
        out = out.push(m.get_or(bottom, none_row).get_or(c, 0))
      }
      bottom = bottom - 1
    }
    if left <= right and top <= bottom {
      for r in range(top, bottom + 1).reverse() {
        out = out.push(m.get_or(r, none_row).get_or(left, 0))
      }
      left = left + 1
    }
  }
  return out
}
