pub fn sudoku(rows: List[Str]) -> Bool {
  if rows.len() != 9 {
    return false
  }
  for row in rows {
    if row.len() != 9 {
      return false
    }
    for ch in row.chars() {
      if not "123456789.".contains(ch) {
        return false
      }
    }
  }
  for r in range(0, 9) {
    let line = rows.get_or(r, "").chars()
    if not group_ok(line) {
      return false
    }
  }
  for c in range(0, 9) {
    let column = range(0, 9).map(fn(rr) => rows.get_or(rr, "").slice(c, c + 1))
    if not group_ok(column) {
      return false
    }
  }
  for br in range(0, 3) {
    for bc in range(0, 3) {
      let box = range(0, 3).flat_map(fn(dr) => range(0, 3).map(fn(dc) => rows.get_or(br * 3 + dr, "").slice(bc * 3 + dc, bc * 3 + dc + 1)))
      if not group_ok(box) {
        return false
      }
    }
  }
  return true
}
