fn one_diff(a: Str, b: Str) -> Bool {
  if a.len() != b.len() {
    return false
  }
  let ca = a.chars()
  let cb = b.chars()
  var diff = 0
  for i in range(0, ca.len()) {
    if ca.get_or(i, "") != cb.get_or(i, "") {
      diff = diff + 1
    }
  }
  return diff == 1
}

pub fn ladder(start: Str, goal: Str, words: List[Str]) -> Int {
  if start == goal {
    return 1
  }
  let nodes = words.unique()
  var seen: Map[Str, Bool] = Map {}
  seen = seen.set(start, true)
  var frontier: List[Str] = [start]
  var steps = 1
  while frontier.len() > 0 {
    var upcoming: List[Str] = []
    for w in frontier {
      for cand in nodes {
        if not seen.has(cand) and one_diff(w, cand) {
          seen = seen.set(cand, true)
          upcoming = upcoming.push(cand)
        }
      }
    }
    steps = steps + 1
    if upcoming.contains(goal) {
      return steps
    }
    frontier = upcoming
  }
  return 0
}
