from collections import OrderedDict


def lru(capacity: int, ops: list[str]) -> list[str]:
    cache = OrderedDict()
    results = []
    for op in ops:
        parts = op.split(" ", 2)
        if parts[0] == "put":
            key, value = parts[1], parts[2]
            if capacity <= 0:
                continue
            if key in cache:
                cache.move_to_end(key)
                cache[key] = value
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = value
        else:
            key = parts[1]
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append("-")
    return results
