def ledger(ops: list[str]) -> dict[str, int]:
    balances: dict[str, int] = {}

    def amount_of(text: str) -> int:
        if not text or not all("0" <= c <= "9" for c in text):
            raise ValueError("bad op")
        value = int(text)
        if value <= 0:
            raise ValueError("bad op")
        return value

    def known(name: str) -> None:
        if name not in balances:
            raise ValueError("unknown " + name)

    for op in ops:
        parts = op.split(" ")
        verb = parts[0]
        if verb == "open" and len(parts) == 2:
            name = parts[1]
            if name in balances:
                raise ValueError("exists " + name)
            balances[name] = 0
        elif verb == "dep" and len(parts) == 3:
            name = parts[1]
            n = amount_of(parts[2])
            known(name)
            balances[name] += n
        elif verb == "wd" and len(parts) == 3:
            name = parts[1]
            n = amount_of(parts[2])
            known(name)
            if balances[name] < n:
                raise ValueError("insufficient " + name)
            balances[name] -= n
        elif verb == "move" and len(parts) == 4:
            src, dst = parts[1], parts[2]
            n = amount_of(parts[3])
            known(src)
            known(dst)
            if balances[src] < n:
                raise ValueError("insufficient " + src)
            balances[src] -= n
            balances[dst] += n
        else:
            raise ValueError("bad op")
