    start = prev = values[0]
    for v in values[1:] + [None]:
        if v is not None and v == prev + 1:
            prev = v
            continue
        length = prev - start + 1
        if length >= 3:
            parts.append(f"{start}-{prev}")
        elif length == 2:
            parts.append(f"{start},{prev}")
        else:
            parts.append(str(start))
        if v is not None:
