import re

_TERM = r"(?:-?[0-9]+|[a-z]+)"
_LINE = re.compile(
    r"([a-z]+) = (" + _TERM + r")((?: [+-] " + _TERM + r")*)"
)
_REST = re.compile(r" ([+-]) (" + _TERM + r")")


def run_vars(lines: list[str]) -> dict[str, int]:
    variables: dict[str, int] = {}

    def value_of(term: str) -> int:
        if term[0] == "-" or term[0].isdigit():
            return int(term)
        if term not in variables:
            raise ValueError("undefined " + term)
        return variables[term]

    for line in lines:
        m = _LINE.fullmatch(line)
        if m is None:
            raise ValueError("syntax error")
        name, first, rest = m.group(1), m.group(2), m.group(3)
        steps = _REST.findall(rest)

        total = value_of(first)
        for op, term in steps:
            v = value_of(term)
            total = total + v if op == "+" else total - v
        variables[name] = total
    return variables
