def lis(xs: list[int]) -> list[int]:
    n = len(xs)
    if n == 0:
        return []

    # f[i] = length of the longest strictly increasing subsequence starting at i.
    f = [1] * n
    for i in range(n - 1, -1, -1):
        best = 1
        for j in range(i + 1, n):
            if xs[j] > xs[i] and f[j] + 1 > best:
                best = f[j] + 1
        f[i] = best

    total = max(f)
    result = []
    prev_index = -1
    need = total
    while need > 0:
        # Pick the smallest value that can still start a subsequence of the
        # remaining length after prev_index (earliest index on ties).
        chosen = -1
        for j in range(prev_index + 1, n):
            if f[j] != need:
                continue
            if prev_index >= 0 and xs[j] <= xs[prev_index]:
                continue
            if chosen == -1 or xs[j] < xs[chosen]:
                chosen = j
        result.append(xs[chosen])
        prev_index = chosen
        need -= 1
    return result
