from collections import deque


def ladder(start: str, goal: str, words: list[str]) -> int:
    if start == goal:
        return 1

    vocab = set(words)
    vocab.discard(start)
    if goal not in vocab:
        return 0

    def one_letter_apart(a: str, b: str) -> bool:
        if len(a) != len(b):
            return False
        diff = 0
        for x, y in zip(a, b):
            if x != y:
                diff += 1
                if diff > 1:
                    return False
        return diff == 1

    dist = {start: 1}
    queue = deque([start])
    while queue:
        word = queue.popleft()
        if word == goal:
            return dist[word]
        for nxt in list(vocab):
            if nxt not in dist and one_letter_apart(word, nxt):
                dist[nxt] = dist[word] + 1
                queue.append(nxt)
                vocab.discard(nxt)
    return 0
