import bisect


def medians(xs: list[int], k: int) -> list[float]:
    n = len(xs)
    if k < 1 or k > n:
        return []

    window = sorted(xs[:k])
    result = []
    for i in range(n - k + 1):
        if i > 0:
            outgoing = xs[i - 1]
            del window[bisect.bisect_left(window, outgoing)]
            bisect.insort(window, xs[i + k - 1])
        if k % 2 == 1:
            result.append(float(window[k // 2]))
        else:
            result.append((window[k // 2 - 1] + window[k // 2]) / 2)
    return result
